"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9756],{4968(n,e,t){t.r(e),t.d(e,{assets:()=>d,contentTitle:()=>c,default:()=>m,frontMatter:()=>l,metadata:()=>o,toc:()=>p});const o=JSON.parse('{"id":"part3-agent-protocols/javascript-typescript-primer","title":"JavaScript and TypeScript Foundations","description":"Welcome! This tutorial starts from absolute first principles: what JavaScript is, what Node.js is, and why we can run code \\"outside the browser\\". You\'ll learn JavaScript in a way that prepares you to write clean, comp...","source":"@site/docs/part3-agent-protocols/06-javascript-typescript-primer.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/06-javascript-typescript-primer","permalink":"/tutorials/part3-agent-protocols/06-javascript-typescript-primer","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":6,"frontMatter":{"title":"JavaScript and TypeScript Foundations","slug":"/part3-agent-protocols/06-javascript-typescript-primer","description":"Welcome! This tutorial starts from absolute first principles: what JavaScript is, what Node.js is, and why we can run code \\"outside the browser\\". You\'ll learn JavaScript in a way that prepares you to write clean, comp...","sidebar_label":"6. JavaScript and TypeScript primer","pagination_label":"6. JavaScript and TypeScript primer","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"5. A2A protocol 1.0","permalink":"/tutorials/part3-agent-protocols/05-a2a-protocol"},"next":{"title":"7. LangChain, LangGraph, and Flowise","permalink":"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise"}}');var r=t(4848),s=t(8453),i=t(8172);const a=JSON.parse('{"sourcePath":"part3-agent-protocols/06-javascript-typescript-primer.html","route":"/part3-agent-protocols/06-javascript-typescript-primer","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"JavaScript and TypeScript Foundations","title":"JavaScript and TypeScript Foundations","description":"Welcome! This tutorial starts from absolute first principles: what JavaScript is, what Node.js is, and why we can run code \\"outside the browser\\". You\'ll learn JavaScript in a way that prepares you to write clean, comp...","readingMinutes":15,"bodyClass":"","normalizeMath":false,"toc":[{"id":"part-1-javascript-fundamentals","label":"Part 1: JavaScript Fundamentals"},{"id":"part-2-typescript-javascript-with-type-safety","label":"Part 2: TypeScript - JavaScript with Type Safety"},{"id":"practice-path-for-mastery","label":"Practice Path for Mastery"},{"id":"example-complete-component","label":"Example: Complete Component"},{"id":"next-steps","label":"Next Steps"}],"html":"<div class=\\"container\\">\\n        \\n        \\n        <div class=\\"intro\\">\\n            <p><strong>Welcome!</strong> This tutorial starts from absolute first principles: what JavaScript is, what Node.js is, and why we can run code \\"outside the browser\\". You\'ll learn JavaScript in a way that prepares you to write clean, component-style code, then transition smoothly into TypeScript.</p>\\n            <p>No web development experience required. No HTML or CSS needed. Just pure programming fundamentals.</p>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h2 id=\\"part-1-javascript-fundamentals\\">Part 1: JavaScript Fundamentals</h2>\\n\\n        <h3 id=\\"1-what-is-javascript\\">1. What is JavaScript?</h3>\\n        <p><strong>JavaScript (JS)</strong> is a programming language that lets you write instructions for a computer to execute. Originally designed for web browsers, JavaScript has evolved into a versatile language used in many contexts.</p>\\n\\n        <p>You can use JavaScript in two main environments:</p>\\n        <ol>\\n            <li><strong>In a web browser</strong> (Chrome, Safari, Firefox, etc.) - for interactive websites</li>\\n            <li><strong>Outside the browser</strong> using <strong>Node.js</strong> - for servers, tools, and applications</li>\\n        </ol>\\n\\n        <h3 id=\\"what-is-node-js\\">What is Node.js?</h3>\\n        <p><strong>Node.js</strong> is a runtime environment - a program you install on your computer that can execute JavaScript files directly, just like Python or Java.</p>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>Key Understanding:</strong></p>\\n            <ul>\\n                <li><strong>JavaScript</strong> = The programming language (the \\"what\\")</li>\\n                <li><strong>Node.js</strong> = The tool that runs JavaScript on your computer (the \\"how\\")</li>\\n                <li>Without Node: Your computer doesn\'t understand <code>.js</code> files</li>\\n                <li>With Node: You can run <code>.js</code> files like any other program</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"2-your-first-hello-world-program\\">2. Your First \\"Hello World\\" Program</h3>\\n        <p>Let\'s write and run the simplest possible JavaScript program.</p>\\n\\n        <div class=\\"step\\">\\n            <p><span class=\\"step-number\\">Step A:</span> Create a folder named <code>js-basics</code> on your computer</p>\\n        </div>\\n\\n        <div class=\\"step\\">\\n            <p><span class=\\"step-number\\">Step B:</span> Inside that folder, create a file named <code>hello.js</code></p>\\n        </div>\\n\\n        <div class=\\"step\\">\\n            <p><span class=\\"step-number\\">Step C:</span> Put this code inside <code>hello.js</code>:</p>\\n        </div>\\n\\n        <pre><code>console.log(\\"Hello world!\\");</code></pre>\\n\\n        <div class=\\"step\\">\\n            <p><span class=\\"step-number\\">Step D:</span> Open a terminal in that folder and run:</p>\\n        </div>\\n\\n        <pre><code>node hello.js</code></pre>\\n\\n        <p>You should see:</p>\\n        <pre><code>Hello world!</code></pre>\\n\\n        <div class=\\"note\\">\\n            <strong>What just happened?</strong>\\n            <ul>\\n                <li><code>hello.js</code> is a text file containing JavaScript code</li>\\n                <li><code>node hello.js</code> means \\"run this file using Node.js\\"</li>\\n                <li><code>console.log(...)</code> prints text to the terminal/console</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"3-how-programs-think-data-and-instructions\\">3. How Programs Think: Data and Instructions</h3>\\n        <p>Every program consists of two fundamental elements:</p>\\n        <ul>\\n            <li><strong>Data</strong> - Information like text, numbers, and true/false values</li>\\n            <li><strong>Instructions</strong> - Commands that tell the computer what to do with that data</li>\\n        </ul>\\n\\n        <h4>Common Data Types in JavaScript</h4>\\n        <table>\\n            <thead>\\n                <tr>\\n                    <th>Type</th>\\n                    <th>Example</th>\\n                    <th>Description</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <tr>\\n                    <td>String</td>\\n                    <td><code>\\"hello\\"</code></td>\\n                    <td>Text (must be in quotes)</td>\\n                </tr>\\n                <tr>\\n                    <td>Number</td>\\n                    <td><code>42</code></td>\\n                    <td>Integers and decimals</td>\\n                </tr>\\n                <tr>\\n                    <td>Boolean</td>\\n                    <td><code>true</code> or <code>false</code></td>\\n                    <td>True/false values</td>\\n                </tr>\\n                <tr>\\n                    <td>Null</td>\\n                    <td><code>null</code></td>\\n                    <td>Intentionally empty value</td>\\n                </tr>\\n                <tr>\\n                    <td>Undefined</td>\\n                    <td><code>undefined</code></td>\\n                    <td>Not yet assigned a value</td>\\n                </tr>\\n            </tbody>\\n        </table>\\n\\n        <pre><code>\\"hello\\"     // text (string)\\n42          // number\\ntrue        // boolean (true/false)\\nnull        // intentionally empty\\nundefined   // not set yet</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"4-variables-storing-data-for-later-use\\">4. Variables: Storing Data for Later Use</h3>\\n        <p>A <strong>variable</strong> is like a labeled container that holds a value. Think of it as a named box where you can store information and retrieve it later.</p>\\n\\n        <h4>Using <code>let</code> (for values that change)</h4>\\n        <pre><code>let score = 0;        // Initial value\\nscore = 10;           // Changed value\\nscore = score + 5;    // Now score is 15\\nconsole.log(score);   // Prints: 15</code></pre>\\n\\n        <h4>Using <code>const</code> (for values that stay the same)</h4>\\n        <pre><code>const username = \\"Sam\\";\\nconsole.log(username);  // Prints: Sam\\n\\n// username = \\"John\\";   // \u274c ERROR! Cannot change a const</code></pre>\\n\\n        <div class=\\"warning\\">\\n            <strong>Beginner Best Practice:</strong> Always use <code>const</code> by default. Only use <code>let</code> when you genuinely need to change the value later. This prevents accidental changes and makes your code easier to understand.\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"5-strings-working-with-text\\">5. Strings: Working with Text</h3>\\n        <p>Strings are sequences of characters used to represent text. JavaScript offers multiple ways to work with strings.</p>\\n\\n        <h4>String Concatenation</h4>\\n        <pre><code>const first = \\"Ada\\";\\nconst last = \\"Lovelace\\";\\n\\n// Old style: using + operator\\nconsole.log(first + \\" \\" + last);  // Ada Lovelace\\n\\n// Modern style: template literals (template strings)\\nconsole.log(`${first} ${last}`);  // Ada Lovelace</code></pre>\\n\\n        <div class=\\"note\\">\\n            Template literals (backticks <code>`</code>) are the modern, preferred way. They\'re easier to read and allow you to embed expressions directly using <code>${...}</code> syntax.\\n        </div>\\n\\n        <h4>More String Examples</h4>\\n        <pre><code>const age = 25;\\nconst message = `I am ${age} years old`;\\nconsole.log(message);  // I am 25 years old\\n\\nconst calculation = `5 + 3 = ${5 + 3}`;\\nconsole.log(calculation);  // 5 + 3 = 8</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"6-numbers-and-arithmetic-operators\\">6. Numbers and Arithmetic Operators</h3>\\n        <p>JavaScript provides standard mathematical operators for working with numbers.</p>\\n\\n        <pre><code>const a = 10;\\nconst b = 3;\\n\\nconsole.log(a + b);  // 13  (addition)\\nconsole.log(a - b);  // 7   (subtraction)\\nconsole.log(a * b);  // 30  (multiplication)\\nconsole.log(a / b);  // 3.333... (division)\\nconsole.log(a % b);  // 1   (remainder/modulo)\\nconsole.log(a ** b); // 1000 (exponentiation: 10\xb3)</code></pre>\\n\\n        <h4>More Complex Operations</h4>\\n        <pre><code>// Order of operations follows standard math rules (PEMDAS)\\nconst result = (10 + 5) * 2;  // 30\\n\\n// Increment and decrement\\nlet counter = 0;\\ncounter++;  // counter is now 1\\ncounter--;  // counter is now 0 again\\n\\n// Compound assignment\\nlet total = 10;\\ntotal += 5;  // Same as: total = total + 5\\ntotal *= 2;  // Same as: total = total * 2</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"7-making-decisions-if-statements\\">7. Making Decisions: If Statements</h3>\\n        <p>Programs need to make choices based on conditions. The <code>if</code> statement lets your code take different paths depending on whether something is true or false.</p>\\n\\n        <h4>Basic If-Else</h4>\\n        <pre><code>const age = 18;\\n\\nif (age &gt;= 18) {\\n  console.log(\\"Adult\\");\\n} else {\\n  console.log(\\"Not adult\\");\\n}</code></pre>\\n\\n        <h4>Multiple Conditions</h4>\\n        <pre><code>const score = 85;\\n\\nif (score &gt;= 90) {\\n  console.log(\\"Grade: A\\");\\n} else if (score &gt;= 80) {\\n  console.log(\\"Grade: B\\");\\n} else if (score &gt;= 70) {\\n  console.log(\\"Grade: C\\");\\n} else {\\n  console.log(\\"Grade: F\\");\\n}</code></pre>\\n\\n        <h4>Comparison Operators</h4>\\n        <table>\\n            <thead>\\n                <tr>\\n                    <th>Operator</th>\\n                    <th>Meaning</th>\\n                    <th>Example</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <tr>\\n                    <td><code>===</code></td>\\n                    <td>Equal to</td>\\n                    <td><code>5 === 5</code> \u2192 true</td>\\n                </tr>\\n                <tr>\\n                    <td><code>!==</code></td>\\n                    <td>Not equal to</td>\\n                    <td><code>5 !== 3</code> \u2192 true</td>\\n                </tr>\\n                <tr>\\n                    <td><code>&gt;</code></td>\\n                    <td>Greater than</td>\\n                    <td><code>5 &gt; 3</code> \u2192 true</td>\\n                </tr>\\n                <tr>\\n                    <td><code>&lt;</code></td>\\n                    <td>Less than</td>\\n                    <td><code>5 &lt; 3</code> \u2192 false</td>\\n                </tr>\\n                <tr>\\n                    <td><code>&gt;=</code></td>\\n                    <td>Greater or equal</td>\\n                    <td><code>5 &gt;= 5</code> \u2192 true</td>\\n                </tr>\\n                <tr>\\n                    <td><code>&lt;=</code></td>\\n                    <td>Less or equal</td>\\n                    <td><code>3 &lt;= 5</code> \u2192 true</td>\\n                </tr>\\n            </tbody>\\n        </table>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"8-repeating-work-loops\\">8. Repeating Work: Loops</h3>\\n        <p>Loops allow you to execute code multiple times without writing the same code over and over.</p>\\n\\n        <h4>The For Loop</h4>\\n        <p>Use when you know exactly how many times to repeat:</p>\\n        <pre><code>// Count from 1 to 5\\nfor (let i = 1; i &lt;= 5; i++) {\\n  console.log(\\"Count:\\", i);\\n}\\n// Output: Count: 1, Count: 2, Count: 3, Count: 4, Count: 5</code></pre>\\n\\n        <div class=\\"note\\">\\n            <strong>For Loop Anatomy:</strong>\\n            <ul>\\n                <li><code>let i = 1</code> - Initialize counter</li>\\n                <li><code>i &lt;= 5</code> - Continue while this is true</li>\\n                <li><code>i++</code> - Increment counter after each iteration</li>\\n            </ul>\\n        </div>\\n\\n        <h4>The For...Of Loop (Easiest for Arrays)</h4>\\n        <p>Use when you want to loop through each item in a list:</p>\\n        <pre><code>const names = [\\"Ava\\", \\"Noah\\", \\"Mia\\"];\\n\\nfor (const name of names) {\\n  console.log(\\"Hello,\\", name);\\n}\\n// Output: Hello, Ava\\n//         Hello, Noah\\n//         Hello, Mia</code></pre>\\n\\n        <h4>While Loop</h4>\\n        <p>Use when you don\'t know how many times you\'ll need to repeat:</p>\\n        <pre><code>let count = 0;\\n\\nwhile (count &lt; 3) {\\n  console.log(\\"Count is:\\", count);\\n  count++;\\n}</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"9-functions-reusable-blocks-of-logic\\">9. Functions: Reusable Blocks of Logic</h3>\\n        <p>A <strong>function</strong> is a named set of instructions that you can run (call) whenever needed. Functions are the foundation of component-style programming.</p>\\n\\n        <h4>Basic Function</h4>\\n        <pre><code>// Define the function\\nfunction add(x, y) {\\n  return x + y;\\n}\\n\\n// Use (call) the function\\nconst result = add(5, 7);\\nconsole.log(result);  // 12</code></pre>\\n\\n        <h4>Functions with Multiple Statements</h4>\\n        <pre><code>function greet(name) {\\n  const message = `Hello, ${name}!`;\\n  console.log(message);\\n  return message;  // Can also return the value\\n}\\n\\ngreet(\\"Alice\\");  // Prints: Hello, Alice!</code></pre>\\n\\n        <h4>Arrow Functions (Modern Syntax)</h4>\\n        <pre><code>// Traditional function\\nfunction multiply(a, b) {\\n  return a * b;\\n}\\n\\n// Arrow function (shorter syntax)\\nconst multiply = (a, b) =&gt; {\\n  return a * b;\\n};\\n\\n// Even shorter (when only returning one expression)\\nconst multiply = (a, b) =&gt; a * b;</code></pre>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>Why Functions Matter for Components:</strong></p>\\n            <p>A component is essentially:</p>\\n            <ul>\\n                <li><strong>Inputs</strong> - Data passed to the function (parameters)</li>\\n                <li><strong>Processing</strong> - Logic inside the function</li>\\n                <li><strong>Outputs</strong> - Data returned from the function</li>\\n            </ul>\\n            <p>Mastering functions is Step #1 toward component-style programming!</p>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"10-objects-grouping-related-data\\">10. Objects: Grouping Related Data</h3>\\n        <p><strong>Objects</strong> are the #1 data structure you\'ll use for component inputs. They group related pieces of data together with named properties.</p>\\n\\n        <h4>Creating and Using Objects</h4>\\n        <pre><code>const settings = {\\n  model: \\"example-model\\",\\n  temperature: 0.7,\\n  maxTokens: 200\\n};\\n\\n// Accessing object properties\\nconsole.log(settings.model);        // example-model\\nconsole.log(settings.temperature);  // 0.7\\nconsole.log(settings.maxTokens);    // 200</code></pre>\\n\\n        <h4>Destructuring (Modern and Clean)</h4>\\n        <p>Extract multiple properties at once:</p>\\n        <pre><code>const { model, maxTokens } = settings;\\nconsole.log(model);     // example-model\\nconsole.log(maxTokens); // 200\\n\\n// This is the same as:\\nconst model = settings.model;\\nconst maxTokens = settings.maxTokens;</code></pre>\\n\\n        <h4>Nested Objects</h4>\\n        <pre><code>const user = {\\n  name: \\"Alice\\",\\n  age: 30,\\n  address: {\\n    city: \\"New York\\",\\n    country: \\"USA\\"\\n  }\\n};\\n\\nconsole.log(user.address.city);  // New York</code></pre>\\n\\n        <div class=\\"note\\">\\n            Think of destructuring as \\"unpacking\\" a config object. This pattern is everywhere in modern JavaScript and component-style code.\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"11-arrays-lists-of-items\\">11. Arrays: Lists of Items</h3>\\n        <p><strong>Arrays</strong> store ordered lists of items - perfect for messages, inputs, results, or any collection of data.</p>\\n\\n        <h4>Creating and Modifying Arrays</h4>\\n        <pre><code>const items = [\\"a\\", \\"b\\", \\"c\\"];\\n\\n// Add to end\\nitems.push(\\"d\\");\\nconsole.log(items);  // [\\"a\\", \\"b\\", \\"c\\", \\"d\\"]\\n\\n// Remove from end\\nconst last = items.pop();\\nconsole.log(last);   // \\"d\\"\\n\\n// Access by index (starts at 0)\\nconsole.log(items[0]);  // \\"a\\"\\nconsole.log(items[1]);  // \\"b\\"</code></pre>\\n\\n        <h4>Essential Array Methods</h4>\\n        <pre><code>const numbers = [1, 2, 3, 4, 5];\\n\\n// map: transform each item\\nconst doubled = numbers.map(n =&gt; n * 2);\\nconsole.log(doubled);  // [2, 4, 6, 8, 10]\\n\\n// filter: keep items that match a condition\\nconst evens = numbers.filter(n =&gt; n % 2 === 0);\\nconsole.log(evens);  // [2, 4]\\n\\n// find: get first item that matches\\nconst firstBig = numbers.find(n =&gt; n &gt; 3);\\nconsole.log(firstBig);  // 4\\n\\n// reduce: combine all items into one value\\nconst sum = numbers.reduce((total, n) =&gt; total + n, 0);\\nconsole.log(sum);  // 15</code></pre>\\n\\n        <h4>Looping Through Arrays</h4>\\n        <pre><code>const fruits = [\\"apple\\", \\"banana\\", \\"cherry\\"];\\n\\n// Method 1: for...of (cleanest)\\nfor (const fruit of fruits) {\\n  console.log(fruit);\\n}\\n\\n// Method 2: forEach (functional style)\\nfruits.forEach(fruit =&gt; {\\n  console.log(fruit);\\n});\\n\\n// Method 3: traditional for loop\\nfor (let i = 0; i &lt; fruits.length; i++) {\\n  console.log(fruits[i]);\\n}</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"12-asynchronous-programming-waiting-for-work-to-complete\\">12. Asynchronous Programming: Waiting for Work to Complete</h3>\\n        <p>This is <strong>the most important modern JavaScript concept</strong>. In real applications, many operations take time:</p>\\n        <ul>\\n            <li>Reading files from disk</li>\\n            <li>Making network requests (API calls)</li>\\n            <li>Querying databases</li>\\n            <li>Any operation that requires waiting</li>\\n        </ul>\\n\\n        <h4>Synchronous vs Asynchronous</h4>\\n        <ul>\\n            <li><strong>Synchronous (sync)</strong>: Code runs line by line, each line waits for the previous to finish</li>\\n            <li><strong>Asynchronous (async)</strong>: You start an operation, let it run in the background, then handle the result when it\'s ready</li>\\n        </ul>\\n\\n        <h4>The Modern Way: async/await</h4>\\n        <pre><code>// Helper function that returns a Promise\\nfunction wait(ms) {\\n  return new Promise(resolve =&gt; setTimeout(resolve, ms));\\n}\\n\\n// Async function can use \'await\' to wait for Promises\\nasync function run() {\\n  console.log(\\"Start\\");\\n  await wait(1000);  // Wait 1 second\\n  console.log(\\"After 1 second\\");\\n  await wait(1000);  // Wait another second\\n  console.log(\\"After 2 seconds\\");\\n}\\n\\nrun();</code></pre>\\n\\n        <h4>Real-World Example: Fetching Data</h4>\\n        <pre><code>// Simulated API call\\nasync function fetchUserData(userId) {\\n  console.log(\\"Fetching user data...\\");\\n  await wait(1000);  // Simulate network delay\\n  \\n  return {\\n    id: userId,\\n    name: \\"Alice\\",\\n    email: \\"alice@example.com\\"\\n  };\\n}\\n\\nasync function main() {\\n  const user = await fetchUserData(123);\\n  console.log(\\"User:\\", user);\\n  console.log(\\"Email:\\", user.email);\\n}\\n\\nmain();</code></pre>\\n\\n        <div class=\\"warning\\">\\n            This skill is <strong>essential</strong> for component-style code. Almost all real-world components perform asynchronous operations.\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"13-error-handling-protecting-your-code\\">13. Error Handling: Protecting Your Code</h3>\\n        <p>Good code anticipates problems and handles them gracefully. The <code>try/catch</code> block lets you catch and handle errors.</p>\\n\\n        <h4>Basic Try/Catch</h4>\\n        <pre><code>function parseJson(text) {\\n  return JSON.parse(text);\\n}\\n\\ntry {\\n  const data = parseJson(\\"{ bad json }\\");\\n  console.log(data);\\n} catch (err) {\\n  console.log(\\"Error parsing JSON:\\", err.message);\\n}</code></pre>\\n\\n        <h4>With Async Functions</h4>\\n        <pre><code>async function fetchData(url) {\\n  try {\\n    // Simulate API call that might fail\\n    if (url === \\"\\") {\\n      throw new Error(\\"URL cannot be empty\\");\\n    }\\n    \\n    const data = await someAsyncOperation(url);\\n    return data;\\n  } catch (err) {\\n    console.error(\\"Failed to fetch:\\", err.message);\\n    return null;  // Return safe default\\n  }\\n}</code></pre>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>Component-Style Error Handling:</strong></p>\\n            <ul>\\n                <li><strong>Validate inputs</strong> early and clearly</li>\\n                <li><strong>Fail with helpful messages</strong> that explain what went wrong</li>\\n                <li><strong>Use try/catch</strong> around risky operations</li>\\n                <li><strong>Return safe defaults</strong> when appropriate</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"14-modules-organizing-code-across-files\\">14. Modules: Organizing Code Across Files</h3>\\n        <p>Real projects split code into multiple files. <strong>Modules</strong> let you export code from one file and import it into another.</p>\\n\\n        <h4>Example: Math Utilities</h4>\\n        <p><strong>File: math.js</strong></p>\\n        <pre><code>// Export individual functions\\nfunction add(a, b) {\\n  return a + b;\\n}\\n\\nfunction subtract(a, b) {\\n  return a - b;\\n}\\n\\nfunction multiply(a, b) {\\n  return a * b;\\n}\\n\\n// Export them\\nmodule.exports = { add, subtract, multiply };</code></pre>\\n\\n        <p><strong>File: index.js</strong></p>\\n        <pre><code>// Import from math.js\\nconst { add, multiply } = require(\\"./math\\");\\n\\nconsole.log(add(2, 3));        // 5\\nconsole.log(multiply(4, 5));   // 20</code></pre>\\n\\n        <p>Run it:</p>\\n        <pre><code>node index.js</code></pre>\\n\\n        <h4>Modern ES Modules (Alternative Syntax)</h4>\\n        <p><strong>File: math.mjs</strong></p>\\n        <pre><code>// Modern export syntax\\nexport function add(a, b) {\\n  return a + b;\\n}\\n\\nexport function multiply(a, b) {\\n  return a * b;\\n}</code></pre>\\n\\n        <p><strong>File: index.mjs</strong></p>\\n        <pre><code>// Modern import syntax\\nimport { add, multiply } from \\"./math.mjs\\";\\n\\nconsole.log(add(2, 3));\\nconsole.log(multiply(4, 5));</code></pre>\\n\\n        <div class=\\"note\\">\\n            <strong>Why This Matters:</strong> Component-style programming is all about creating reusable, modular code. Each component typically lives in its own file and exports its functionality.\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h2 id=\\"part-2-typescript-javascript-with-type-safety\\">Part 2: TypeScript - JavaScript with Type Safety</h2>\\n\\n        <h3 id=\\"what-is-typescript\\">What is TypeScript?</h3>\\n        <p><strong>TypeScript</strong> is JavaScript plus <strong>type annotations</strong>. It helps you catch mistakes before running your code.</p>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>The Problem TypeScript Solves:</strong></p>\\n            <pre><code>// JavaScript allows this mistake:\\nconst x = \\"10\\";         // x is a string\\nconsole.log(x * 2);     // 20 (JavaScript converts it)\\n// But what if you didn\'t intend that?\\n\\n// TypeScript catches it:\\nconst x: number = \\"10\\";  // \u274c ERROR: Type \'string\' not assignable to \'number\'</code></pre>\\n        </div>\\n\\n        <h3 id=\\"1-installing-typescript\\">1. Installing TypeScript</h3>\\n        <p>In your project folder, run these commands:</p>\\n\\n        <pre><code># Initialize a new Node.js project\\nnpm init -y\\n\\n# Install TypeScript as a development dependency\\nnpm install -D typescript\\n\\n# Create TypeScript configuration file\\nnpx tsc --init</code></pre>\\n\\n        <div class=\\"note\\">\\n            This creates a <code>tsconfig.json</code> file that configures how TypeScript compiles your code.\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"2-your-first-typescript-file\\">2. Your First TypeScript File</h3>\\n        <p>Create a file named <code>index.ts</code>:</p>\\n\\n        <pre><code>const name: string = \\"Sam\\";\\nconst age: number = 30;\\nconst isActive: boolean = true;\\n\\nconsole.log(name, age, isActive);</code></pre>\\n\\n        <p>Compile TypeScript to JavaScript:</p>\\n        <pre><code>npx tsc</code></pre>\\n\\n        <p>This creates <code>index.js</code>. Now run it:</p>\\n        <pre><code>node index.js</code></pre>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>The TypeScript Workflow:</strong></p>\\n            <ol>\\n                <li>Write code in <code>.ts</code> files (TypeScript)</li>\\n                <li>Compile with <code>npx tsc</code> \u2192 creates <code>.js</code> files (JavaScript)</li>\\n                <li>Run the JavaScript with <code>node</code></li>\\n            </ol>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"3-essential-typescript-types\\">3. Essential TypeScript Types</h3>\\n\\n        <h4>Primitive Types</h4>\\n        <pre><code>const enabled: boolean = true;\\nconst count: number = 5;\\nconst label: string = \\"hello\\";\\nconst nothing: null = null;\\nconst notSet: undefined = undefined;</code></pre>\\n\\n        <h4>Arrays</h4>\\n        <pre><code>// Array of strings\\nconst tags: string[] = [\\"javascript\\", \\"typescript\\"];\\n\\n// Array of numbers\\nconst scores: number[] = [90, 85, 92];\\n\\n// Alternative syntax (less common)\\nconst names: Array&lt;string&gt; = [\\"Alice\\", \\"Bob\\"];</code></pre>\\n\\n        <h4>Objects (The Most Important)</h4>\\n        <pre><code>// Define the shape with \'type\'\\ntype User = {\\n  id: number;\\n  name: string;\\n  email: string;\\n  isActive: boolean;\\n};\\n\\nconst user: User = {\\n  id: 1,\\n  name: \\"Alice\\",\\n  email: \\"alice@example.com\\",\\n  isActive: true\\n};\\n\\n// TypeScript ensures all properties exist\\nconsole.log(user.name);  // valid\\nconsole.log(user.age);   // \u274c ERROR: Property \'age\' doesn\'t exist</code></pre>\\n\\n        <h4>Optional Properties</h4>\\n        <pre><code>type Settings = {\\n  model: string;\\n  temperature: number;\\n  maxTokens?: number;  // \u2190 Optional (? makes it optional)\\n};\\n\\n// This is valid (maxTokens is optional)\\nconst settings: Settings = {\\n  model: \\"configured-model-id\\",\\n  temperature: 0.7\\n};</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"4-functions-with-types\\">4. Functions with Types</h3>\\n        <p>TypeScript lets you specify types for function parameters and return values.</p>\\n\\n        <h4>Basic Typed Function</h4>\\n        <pre><code>function add(a: number, b: number): number {\\n  return a + b;\\n}\\n\\nconst result = add(5, 7);    // valid\\nconst bad = add(\\"5\\", \\"7\\");   // \u274c ERROR: Argument type \'string\' not assignable</code></pre>\\n\\n        <h4>Arrow Functions</h4>\\n        <pre><code>const multiply = (a: number, b: number): number =&gt; {\\n  return a * b;\\n};\\n\\n// Shorthand\\nconst divide = (a: number, b: number): number =&gt; a / b;</code></pre>\\n\\n        <h4>Async Functions</h4>\\n        <pre><code>async function fetchUserName(id: number): Promise&lt;string&gt; {\\n  // Simulate API call\\n  await new Promise(resolve =&gt; setTimeout(resolve, 100));\\n  return `User_${id}`;\\n}\\n\\n// Using it\\nasync function main() {\\n  const name = await fetchUserName(123);\\n  console.log(name);  // name is type \'string\'\\n}\\n\\nmain();</code></pre>\\n\\n        <div class=\\"note\\">\\n            <code>Promise&lt;string&gt;</code> means \\"this async function will eventually return a string\\".\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"5-component-style-function-pattern\\">5. Component-Style Function Pattern</h3>\\n        <p>This is the pattern you\'ll use constantly for building components. It combines everything you\'ve learned.</p>\\n\\n        <pre><code>// Define input shape\\ntype Input = {\\n  text: string;\\n  repeat: number;\\n};\\n\\n// Define output shape\\ntype Output = {\\n  result: string;\\n  length: number;\\n};\\n\\n// Validation function\\nfunction validateInput(input: Input): void {\\n  if (input.repeat &lt; 1) {\\n    throw new Error(\\"repeat must be at least 1\\");\\n  }\\n  if (input.repeat &gt; 100) {\\n    throw new Error(\\"repeat cannot exceed 100\\");\\n  }\\n  if (!input.text || input.text.trim() === \\"\\") {\\n    throw new Error(\\"text cannot be empty\\");\\n  }\\n}\\n\\n// Main processing function\\nexport async function run(input: Input): Promise&lt;Output&gt; {\\n  // Step 1: Validate\\n  validateInput(input);\\n  \\n  // Step 2: Process\\n  const repeated = Array(input.repeat).fill(input.text).join(\\" \\");\\n  \\n  // Step 3: Return structured output\\n  return {\\n    result: repeated,\\n    length: repeated.length\\n  };\\n}\\n\\n// Example usage\\nasync function example() {\\n  try {\\n    const output = await run({\\n      text: \\"Hello\\",\\n      repeat: 3\\n    });\\n    \\n    console.log(output.result);  // \\"Hello Hello Hello\\"\\n    console.log(output.length);  // 17\\n  } catch (err) {\\n    console.error(\\"Error:\\", err.message);\\n  }\\n}\\n\\nexample();</code></pre>\\n\\n        <div class=\\"key-concept\\">\\n            <p><strong>This Pattern Teaches:</strong></p>\\n            <ul>\\n                <li><strong>Clean inputs</strong> - Well-defined type for what goes in</li>\\n                <li><strong>Validation</strong> - Check inputs before processing</li>\\n                <li><strong>Predictable output</strong> - Well-defined type for what comes out</li>\\n                <li><strong>Async-ready</strong> - Can handle asynchronous operations</li>\\n                <li><strong>Error handling</strong> - Fails gracefully with clear messages</li>\\n                <li><strong>Exportable</strong> - Can be imported and reused in other files</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h3 id=\\"advanced-typescript-features\\">Advanced TypeScript Features</h3>\\n\\n        <h4>Union Types (Multiple Possible Types)</h4>\\n        <pre><code>type Status = \\"pending\\" | \\"success\\" | \\"error\\";\\n\\nfunction handleStatus(status: Status) {\\n  if (status === \\"pending\\") {\\n    console.log(\\"Loading...\\");\\n  } else if (status === \\"success\\") {\\n    console.log(\\"Done!\\");\\n  } else {\\n    console.log(\\"Failed!\\");\\n  }\\n}\\n\\nhandleStatus(\\"success\\");   // valid\\nhandleStatus(\\"loading\\");   // \u274c ERROR: Not a valid Status</code></pre>\\n\\n        <h4>Interfaces (Alternative to Type)</h4>\\n        <pre><code>interface User {\\n  id: number;\\n  name: string;\\n  email: string;\\n}\\n\\n// Interfaces can extend\\ninterface Admin extends User {\\n  permissions: string[];\\n}\\n\\nconst admin: Admin = {\\n  id: 1,\\n  name: \\"Alice\\",\\n  email: \\"alice@example.com\\",\\n  permissions: [\\"read\\", \\"write\\", \\"delete\\"]\\n};</code></pre>\\n\\n        <h4>Generic Types (Reusable Type Patterns)</h4>\\n        <pre><code>// Generic array wrapper\\nfunction wrapInArray&lt;T&gt;(item: T): T[] {\\n  return [item];\\n}\\n\\nconst nums = wrapInArray(42);        // number[]\\nconst strs = wrapInArray(\\"hello\\");   // string[]\\n\\n// Generic API response\\ntype ApiResponse&lt;T&gt; = {\\n  data: T;\\n  status: number;\\n  message: string;\\n};\\n\\nconst userResponse: ApiResponse&lt;User&gt; = {\\n  data: { id: 1, name: \\"Alice\\", email: \\"alice@example.com\\" },\\n  status: 200,\\n  message: \\"Success\\"\\n};</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h2 id=\\"practice-path-for-mastery\\">Practice Path for Mastery</h2>\\n\\n        <div class=\\"practice-box\\">\\n            <h3 id=\\"beginner-to-component-developer-roadmap\\">Beginner-to-Component-Developer Roadmap</h3>\\n            <p>Complete these exercises in order to master component-style programming:</p>\\n            \\n            <ol>\\n                <li>\\n                    <strong>Simple Function</strong><br>\\n                    Write a function that takes an object with <code>{ firstName, lastName }</code> and returns <code>{ fullName }</code>\\n                </li>\\n                \\n                <li>\\n                    <strong>Add Validation</strong><br>\\n                    Enhance the function to throw an error if either name is empty\\n                </li>\\n                \\n                <li>\\n                    <strong>Make it Async</strong><br>\\n                    Convert it to an async function that waits 500ms before returning (simulating a database lookup)\\n                </li>\\n                \\n                <li>\\n                    <strong>Split into Modules</strong><br>\\n                    Move the function to a separate file and import it in your main file\\n                </li>\\n                \\n                <li>\\n                    <strong>Convert to TypeScript</strong><br>\\n                    Add proper types for input, output, and the function signature\\n                </li>\\n                \\n                <li>\\n                    <strong>Build a Real Component</strong><br>\\n                    Create a \\"user profile\\" component that takes user data, validates it, and returns formatted profile information\\n                </li>\\n            </ol>\\n        </div>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h2 id=\\"example-complete-component\\">Example: Complete Component</h2>\\n        <p>Here\'s a complete, real-world style component combining all concepts:</p>\\n\\n        <pre><code>// types.ts - Type definitions\\nexport type UserInput = {\\n  username: string;\\n  email: string;\\n  age?: number;\\n};\\n\\nexport type ValidationResult = {\\n  isValid: boolean;\\n  errors: string[];\\n};\\n\\nexport type ProcessedUser = {\\n  username: string;\\n  email: string;\\n  age: number;\\n  createdAt: string;\\n};\\n\\n// validators.ts - Validation logic\\nexport function validateUser(input: UserInput): ValidationResult {\\n  const errors: string[] = [];\\n  \\n  if (!input.username || input.username.length &lt; 3) {\\n    errors.push(\\"Username must be at least 3 characters\\");\\n  }\\n  \\n  if (!input.email || !input.email.includes(\\"@\\")) {\\n    errors.push(\\"Valid email is required\\");\\n  }\\n  \\n  if (input.age !== undefined &amp;&amp; (input.age &lt; 0 || input.age &gt; 120)) {\\n    errors.push(\\"Age must be between 0 and 120\\");\\n  }\\n  \\n  return {\\n    isValid: errors.length === 0,\\n    errors\\n  };\\n}\\n\\n// component.ts - Main component logic\\nimport { UserInput, ValidationResult, ProcessedUser } from \\"./types\\";\\nimport { validateUser } from \\"./validators\\";\\n\\nexport async function processUser(input: UserInput): Promise&lt;ProcessedUser&gt; {\\n  // Validate input\\n  const validation = validateUser(input);\\n  \\n  if (!validation.isValid) {\\n    throw new Error(`Validation failed: ${validation.errors.join(\\", \\")}`);\\n  }\\n  \\n  // Simulate async processing (e.g., database save)\\n  await new Promise(resolve =&gt; setTimeout(resolve, 100));\\n  \\n  // Return processed result\\n  return {\\n    username: input.username,\\n    email: input.email.toLowerCase(),\\n    age: input.age ?? 0,  // Default to 0 if not provided\\n    createdAt: new Date().toISOString()\\n  };\\n}\\n\\n// index.ts - Usage example\\nimport { processUser } from \\"./component\\";\\n\\nasync function main() {\\n  try {\\n    const result = await processUser({\\n      username: \\"alice123\\",\\n      email: \\"Alice@Example.com\\",\\n      age: 25\\n    });\\n    \\n    console.log(\\"User processed:\\", result);\\n  } catch (err) {\\n    console.error(\\"Failed to process user:\\", err.message);\\n  }\\n}\\n\\nmain();</code></pre>\\n\\n        <div class=\\"divider\\"></div>\\n\\n        <h2 id=\\"next-steps\\">Next Steps</h2>\\n        <ul>\\n            <li>Practice building small components with clear input/output types</li>\\n            <li>Learn about popular frameworks that use this pattern (React, Vue, etc.)</li>\\n            <li>Explore Node.js libraries for file I/O, HTTP requests, and databases</li>\\n            <li>Study design patterns (Factory, Builder, Strategy) in TypeScript</li>\\n            <li>Build a complete application with multiple interconnected components</li>\\n        </ul>\\n\\n        <div class=\\"note\\">\\n            <strong>Remember:</strong> The best way to learn is by building. Start small, make mistakes, and gradually increase complexity. Every expert programmer started exactly where you are now!\\n        </div>\\n    </div>"}'),l={title:"JavaScript and TypeScript Foundations",slug:"/part3-agent-protocols/06-javascript-typescript-primer",description:'Welcome! This tutorial starts from absolute first principles: what JavaScript is, what Node.js is, and why we can run code "outside the browser". You\'ll learn JavaScript in a way that prepares you to write clean, comp...',sidebar_label:"6. JavaScript and TypeScript primer",pagination_label:"6. JavaScript and TypeScript primer",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function u(n){return(0,r.jsx)(i.A,{content:a})}function m(n={}){const{wrapper:e}={...(0,s.R)(),...n.components};return e?(0,r.jsx)(e,{...n,children:(0,r.jsx)(u,{...n})}):u()}}}]);